head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > P > toggleButtonEvent]<br/>트리 아이템을 접거나 펼치기 위해 토글 버튼에서 인식할 마우스 액션을 설정합니다.",
    "validation" : [        
        "미설정 또는 onclick 설정 시 트리 아이템의 토글 버튼을 마우스로 클릭하면 자식 트리 아이템이 확장/축소됩니다.",
        "onmousedown 설정 시 트리 아이템의 토글 버튼을 마우스 왼쪽 버튼으로 누르는 순간 자식 트리 아이템이 확장/축소됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {           
        toggleButtonEvent : con_toggleButtonEvent.getText(),
    }

    let cList = $c.gcm.createCList(properties);   
    let eList = $c.gcm.createEList(["onclick", "onmousedown"]);   

    $c.gcm.createBasicTreeView(cList, eList); 
}



scwin.btn_isOpen_onclick = function (e) {   
    for (var i = 1; i < 12; i++)    
        wf_body_bottom.getObj("scwin").setReturnValue("item("+i+") : " + target1.isOpen(i));   
};



scwin.target1_onclick = function (e) {
    let toggleButtonEvent = target1.options.toggleButtonEvent

    if (toggleButtonEvent == "" || toggleButtonEvent == "onclick") {
        wf_body_bottom.getObj("scwin").setReturnValue("target1_onclick");
        scwin.btn_isOpen_onclick();
    }
}



scwin.target1_onmousedown = function (e) {
    let toggleButtonEvent = target1.options.toggleButtonEvent

    if (toggleButtonEvent == "onmousedown") {
        wf_body_bottom.getObj("scwin").setReturnValue("target1_onmousedown");
        scwin.btn_isOpen_onclick();
    }
}
